        if x1 <= xCenter <= x2 and y1 <= yCenter <= y2:
            return True
        def seg_dist(ax, ay, bx, by):
            dx, dy = bx - ax, by - ay
            t = max(0.0, min(1.0, ((xCenter - ax) * dx + (yCenter - ay) * dy) / (dx * dx + dy * dy)))
            px, py = ax + t * dx, ay + t * dy
            return (xCenter - px) ** 2 + (yCenter - py) ** 2
        r2 = radius * radius
        return (seg_dist(x1, y1, x2, y1) <= r2 or seg_dist(x1, y2, x2, y2) <= r2 or
                seg_dist(x1, y1, x1, y2) <= r2 or seg_dist(x2, y1, x2, y2) <= r2)

