class Solution {
public:
    bool checkOverlap(int radius, int xCenter, int yCenter, int x1, int y1, int x2, int y2) {
        if (x1 <= xCenter && xCenter <= x2 && y1 <= yCenter && yCenter <= y2) return true;
        auto segDist = [&](long long ax, long long ay, long long bx, long long by) {
            long long dx = bx - ax, dy = by - ay;
            double t = ((double)(xCenter - ax) * dx + (double)(yCenter - ay) * dy) / (dx * dx + dy * dy);
            t = max(0.0, min(1.0, t));
            double px = ax + t * dx, py = ay + t * dy;
            return (xCenter - px) * (xCenter - px) + (yCenter - py) * (yCenter - py);
        };
        long long r2 = (long long)radius * radius;
        return segDist(x1, y1, x2, y1) <= r2 || segDist(x1, y2, x2, y2) <= r2 ||
               segDist(x1, y1, x1, y2) <= r2 || segDist(x2, y1, x2, y2) <= r2;
    }
};

