class Solution {
    public boolean checkOverlap(int radius, int xCenter, int yCenter, int x1, int y1, int x2, int y2) {
        if (x1 <= xCenter && xCenter <= x2 && y1 <= yCenter && yCenter <= y2) return true;
        long r2 = (long) radius * radius;
        return segDist(xCenter, yCenter, x1, y1, x2, y1) <= r2
            || segDist(xCenter, yCenter, x1, y2, x2, y2) <= r2
            || segDist(xCenter, yCenter, x1, y1, x1, y2) <= r2
            || segDist(xCenter, yCenter, x2, y1, x2, y2) <= r2;
    }
    private long segDist(int px, int py, long ax, long ay, long bx, long by) {
        long dx = bx - ax, dy = by - ay;
        double t = ((double)(px - ax) * dx + (double)(py - ay) * dy) / (dx * dx + dy * dy);
        t = Math.max(0.0, Math.min(1.0, t));
        double qx = ax + t * dx, qy = ay + t * dy;
        double ddx = px - qx, ddy = py - qy;
        return (long)(ddx * ddx + ddy * ddy);
    }
}

